list_categories.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.categories().listCategories(
        Map.of("limit", 10, "offset", 10, "sort", "name", "dir", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("categories")) {
    Map<?, ?> category = (Map<?, ?>) row;
    Map<?, ?> general = (Map<?, ?>) category.get("general");
    System.out.println(category.get("id") + " " + general.get("name") + " " + general.get("url"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

