create_category.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.categories().createCategory(Map.of("category", Map.of(
        "general", Map.of("name", "Seasonal Produce", "title", "Seasonal Produce",
                "heading", "Fresh this season", "summary", "Fruit and vegetables picked this week",
                "parent_category", Map.of("id", 4310)),
        "description", Map.of("content", "<p>What is in season right now.</p>"),
        "availability_visibility", Map.of("visible", true, "custom_sorting", true, "default_sorting", "alpha_asc"),
        "tax_shipping", Map.of("tax_message", "Prices include GST"),
        "assign_products", Map.of("products", List.of(101, 102)))));
Map<?, ?> category = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("category");
Map<?, ?> general = (Map<?, ?>) category.get("general");
System.out.println(category.get("id") + " " + general.get("sku") + " " + general.get("url"));

