patch_category_section.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.categories().patchCategorySection(4321, "assign_products",
        Map.of("category", Map.of("assign_products", Map.of("products", List.of(101, 102, 103)))));
Map<?, ?> category = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("category");
for (Object row : (List<?>) ((Map<?, ?>) category.get("assign_products")).get("products")) {
    Map<?, ?> product = (Map<?, ?>) row;
    System.out.println(product.get("id") + " " + product.get("name") + " " + product.get("sku"));
}
